# Stop-Services.ps1
# PowerShell script to cleanly stop all Stage 4 microservices

Write-Host "================================================" -ForegroundColor Cyan
Write-Host "Stopping E-Commerce Microservices (Stage 4)..." -ForegroundColor Cyan
Write-Host "================================================" -ForegroundColor Cyan

if (Test-Path "services-pids.json") {
    $pids = Get-Content -Raw "services-pids.json" | ConvertFrom-Json
    foreach ($name in $pids.PSObject.Properties.Name) {
        $pidVal = $pids.$name
        if ($pidVal) {
            Write-Host "Stopping service $name (PID: $pidVal)..." -ForegroundColor Yellow
            try {
                Stop-Process -Id $pidVal -Force -ErrorAction SilentlyContinue
                Write-Host "Service $name stopped." -ForegroundColor Green
            } catch {
                Write-Host "Failed to stop service $name or it was already terminated." -ForegroundColor Red
            }
        }
    }
    Remove-Item "services-pids.json" -ErrorAction SilentlyContinue
} else {
    Write-Host "services-pids.json not found. Attempting fallback process cleanup..." -ForegroundColor Yellow
}

# Fallback cleanup of any orphaned backend services on ports 18400-18403 and frontend 18500
$ports = @(18400, 18401, 18402, 18403, 18500)
foreach ($port in $ports) {
    try {
        $netsat = Get-NetTCPConnection -LocalPort $port -ErrorAction SilentlyContinue
        if ($netsat) {
            foreach ($conn in $netsat) {
                if ($conn.OwningProcess -ne 0) {
                    Write-Host "Forcibly killing orphaned process on port $port (PID: $($conn.OwningProcess))..." -ForegroundColor Red
                    Stop-Process -Id $conn.OwningProcess -Force -ErrorAction SilentlyContinue
                }
            }
        }
    } catch {
        # ignore
    }
}

Write-Host "================================================" -ForegroundColor Green
Write-Host "All Stage 4 microservices stopped successfully!" -ForegroundColor Green
Write-Host "================================================" -ForegroundColor Green

